using System;using System.Drawing;using System.Drawing.Imaging;using System.Drawing.Drawing2D;using System.IO;using System.Linq;
namespace IDSketcher {
class ThreeDView {
 public GlbModel Model;public float X,Y,Scale=1,Yaw=-25,Pitch=15,Lens=50;public bool FullQuality,Interacting;
 public ThreeDView Copy(){return new ThreeDView{Model=Model,X=X,Y=Y,Scale=Scale,Yaw=Yaw,Pitch=Pitch,Lens=Lens};}
 public void Write(BinaryWriter w){w.Write(Model.Source.Length);w.Write(Model.Source);w.Write(X);w.Write(Y);w.Write(Scale);w.Write(Yaw);w.Write(Pitch);w.Write(Lens);}
 public static ThreeDView Read(BinaryReader r,bool hasLens=true){int n=r.ReadInt32();if(n<20||n>200000000||n>r.BaseStream.Length-r.BaseStream.Position)throw new InvalidDataException("Invalid embedded 3D model.");var view=new ThreeDView{Model=GlbModel.Load(r.ReadBytes(n)),X=r.ReadSingle(),Y=r.ReadSingle(),Scale=r.ReadSingle(),Yaw=r.ReadSingle(),Pitch=r.ReadSingle()};if(hasLens){view.Lens=r.ReadSingle();if(float.IsNaN(view.Lens)||view.Lens<30||view.Lens>100)throw new InvalidDataException("Invalid lens.");}foreach(float f in new[]{view.X,view.Y,view.Scale,view.Yaw,view.Pitch})if(float.IsNaN(f)||float.IsInfinity(f)||Math.Abs(f)>1000000)throw new InvalidDataException("Invalid 3D view.");if(view.Scale<.05||view.Scale>20||Math.Abs(view.Pitch)>89)throw new InvalidDataException("Invalid 3D zoom or orbit.");return view;}
 struct Projected {public float X,Y,Q,U,V,Light,R,G,B,A;public Vec3 Position,Normal;}
 float yawCos,yawSin,pitchCos,pitchSin;Vec3 Rotate(Vec3 p){float x=p.X*yawCos+p.Z*yawSin,z=-p.X*yawSin+p.Z*yawCos;return new Vec3(x,p.Y*pitchCos-z*pitchSin,p.Y*pitchSin+z*pitchCos);}
 static float Light(Vec3 n){n=n.Unit();return .28f+.72f*Math.Max(0,n.X*-.25f+n.Y*.45f+n.Z*.857f);}
 public Bitmap Render(int width,int height){
  float baseRatio=FullQuality?1:Math.Min(1,(Interacting?900f:1800f)/Math.Max(width,height));float sample=Interacting?1:2;
  float ratio=Math.Min(baseRatio*sample,(float)Math.Sqrt(16000000.0/width/height));int w=Math.Max(1,(int)Math.Round(width*ratio)),h=Math.Max(1,(int)Math.Round(height*ratio));
  using(var image=Raster(w,h,ratio)){var full=new Bitmap(width,height,PixelFormat.Format32bppPArgb);using(var g=Graphics.FromImage(full)){g.CompositingMode=CompositingMode.SourceCopy;g.InterpolationMode=InterpolationMode.HighQualityBicubic;g.PixelOffsetMode=PixelOffsetMode.Half;g.DrawImage(image,new Rectangle(0,0,width,height));}return full;}
 }
 unsafe Bitmap Raster(int w,int h,float ratio){yawCos=(float)Math.Cos(Yaw*Math.PI/180);yawSin=(float)Math.Sin(Yaw*Math.PI/180);pitchCos=(float)Math.Cos(Pitch*Math.PI/180);pitchSin=(float)Math.Sin(Pitch*Math.PI/180);var image=new Bitmap(w,h,PixelFormat.Format32bppArgb);var depth=new float[w*h];for(int i=0;i<depth.Length;i++)depth[i]=float.PositiveInfinity;var projected=new Projected[Model.Vertices.Length];float focal=Math.Min(w,h)*1.1f*Scale;for(int i=0;i<projected.Length;i++){var v=Model.Vertices[i];var p=Rotate(v.P);float distance=3.5f*Lens/50f;float q=(Lens/50f)/(distance-p.Z);var n=Rotate(v.N);projected[i]=new Projected{X=X*ratio+p.X*focal*q,Y=Y*ratio-p.Y*focal*q,Q=q,U=v.U,V=v.V,R=v.R,G=v.G,B=v.B,A=v.A,Position=p,Normal=n,Light=Light(n)};}
 var data=image.LockBits(new Rectangle(0,0,w,h),ImageLockMode.WriteOnly,PixelFormat.Format32bppArgb);try{var transparent=Model.Triangles.Where(t=>Model.Materials[t.Material].Alpha=="BLEND").OrderBy(t=>projected[t.A].Q+projected[t.B].Q+projected[t.C].Q);foreach(var triangle in Model.Triangles.Where(t=>Model.Materials[t.Material].Alpha!="BLEND").Concat(transparent)){var a=projected[triangle.A];var b=projected[triangle.B];var c=projected[triangle.C];var material=Model.Materials[triangle.Material];float area=(b.X-a.X)*(c.Y-a.Y)-(b.Y-a.Y)*(c.X-a.X);if(Math.Abs(area)<.00001||!material.DoubleSided&&area>=0)continue;int minX=Math.Max(0,(int)Math.Floor(Math.Min(a.X,Math.Min(b.X,c.X)))),maxX=Math.Min(w-1,(int)Math.Ceiling(Math.Max(a.X,Math.Max(b.X,c.X)))),minY=Math.Max(0,(int)Math.Floor(Math.Min(a.Y,Math.Min(b.Y,c.Y)))),maxY=Math.Min(h-1,(int)Math.Ceiling(Math.Max(a.Y,Math.Max(b.Y,c.Y))));if(minX>maxX||minY>maxY)continue;var face=Vec3.Cross(b.Position-a.Position,c.Position-a.Position);if(area>0)face=face*-1;float faceLight=Light(face);bool normals=a.Normal.Length()>.01&&b.Normal.Length()>.01&&c.Normal.Length()>.01;var texture=material.Texture<0?null:Model.Textures[material.Texture];for(int y=minY;y<=maxY;y++){int* row=(int*)((byte*)data.Scan0+y*data.Stride);for(int x=minX;x<=maxX;x++){float px=x+.5f,py=y+.5f,wa=((b.X-px)*(c.Y-py)-(b.Y-py)*(c.X-px))/area,wb=((c.X-px)*(a.Y-py)-(c.Y-py)*(a.X-px))/area,wc=1-wa-wb;if(wa<-.000001||wb<-.000001||wc<-.000001)continue;float q=wa*a.Q+wb*b.Q+wc*c.Q,z=1/q;int index=y*w+x;if(z>depth[index]+.000001)continue;wa=wa*a.Q/q;wb=wb*b.Q/q;wc=wc*c.Q/q;float tr=1,tg=1,tb=1,ta=1;if(texture!=null){float u=wa*a.U+wb*b.U+wc*c.U,v=wa*a.V+wb*b.V+wc*c.V;u-=(float)Math.Floor(u);v-=(float)Math.Floor(v);int colour=texture.Pixels[Math.Min(texture.Height-1,(int)(v*texture.Height))*texture.Width+Math.Min(texture.Width-1,(int)(u*texture.Width))];tr=((colour>>16)&255)/255f;tg=((colour>>8)&255)/255f;tb=(colour&255)/255f;ta=((uint)colour>>24)/255f;}tr*=wa*a.R+wb*b.R+wc*c.R;tg*=wa*a.G+wb*b.G+wc*c.G;tb*=wa*a.B+wb*b.B+wc*c.B;float alpha=material.A*ta*(wa*a.A+wb*b.A+wc*c.A);if(material.Alpha=="MASK"){if(alpha<material.Cutoff)continue;alpha=1;}else if(material.Alpha!="BLEND")alpha=1;if(alpha<=.001)continue;float light=material.Unlit?1:normals?wa*a.Light+wb*b.Light+wc*c.Light:faceLight;int r=(int)Math.Min(255,255*material.R*tr*light),g=(int)Math.Min(255,255*material.G*tg*light),blue=(int)Math.Min(255,255*material.B*tb*light);if(alpha<.999){int old=row[x];float oldAlpha=((uint)old>>24)/255f,combined=alpha+oldAlpha*(1-alpha);r=(int)((r*alpha+((old>>16)&255)*oldAlpha*(1-alpha))/combined);g=(int)((g*alpha+((old>>8)&255)*oldAlpha*(1-alpha))/combined);blue=(int)((blue*alpha+(old&255)*oldAlpha*(1-alpha))/combined);alpha=combined;}row[x]=((int)(alpha*255)<<24)|(r<<16)|(g<<8)|blue;depth[index]=z;}}}}finally{image.UnlockBits(data);}return image;}
}
partial class Layer {public ThreeDView Scene;public bool Is3D{get{return Scene!=null;}}public bool IsRaster{get{return !IsVector&&!Is3D;}}}

}
